<script setup>
import {computed,onMounted,ref} from 'vue';import {tempsTravailService} from '@/services/tempsTravailService';import {employeService} from '@/services/employeService'
const employe=ref(null),creneaux=ref([]),date=ref(new Date()),erreur=ref(''),commentaires=ref({}),iso=d=>d.toISOString().slice(0,10),debut=computed(()=>new Date(date.value.getFullYear(),date.value.getMonth(),1)),fin=computed(()=>new Date(date.value.getFullYear(),date.value.getMonth()+1,0,23,59,59))
async function load(){creneaux.value=await tempsTravailService.creneaux(employe.value.id,debut.value.toISOString().slice(0,19),fin.value.toISOString().slice(0,19))}async function declarer(c,s){try{const x=await tempsTravailService.declarerCreneau(c.id,s,commentaires.value[c.id]||'');Object.assign(c,x)}catch(e){erreur.value=e.response?.data?.message||'Déclaration impossible.'}}function nav(n){date.value=new Date(date.value.getFullYear(),date.value.getMonth()+n,1);load()}onMounted(async()=>{try{employe.value=await employeService.moi();await load()}catch(e){erreur.value='Calendrier indisponible.'}})
</script>
<template><div class="container-fluid py-4"><div class="card shadow-sm"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><h1 class="h3">Mon calendrier de travail</h1><div><button class="btn btn-outline-secondary" @click="nav(-1)">‹</button><strong class="mx-3">{{date.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}}</strong><button class="btn btn-outline-secondary" @click="nav(1)">›</button></div></div><p v-if="erreur" class="alert alert-danger">{{erreur}}</p><div class="row g-3 mt-2"><div v-for="c in creneaux" :key="c.id" class="col-md-6 col-xl-4"><article class="border rounded p-3 h-100"><h2 class="h6">{{c.libelle||'Travail'}}</h2><div>{{new Date(c.dateDebut).toLocaleDateString('fr-FR')}} · {{new Date(c.dateDebut).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}} – {{new Date(c.dateFin).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}}</div><span class="badge text-bg-light mt-2">{{c.statutEmploye||'NON_COMMENCE'}}</span><span v-if="c.statutValidation==='EN_ATTENTE'" class="badge text-bg-warning ms-1">En attente du supérieur</span><textarea v-model="commentaires[c.id]" class="form-control form-control-sm mt-2" rows="2" placeholder="Commentaire"></textarea><div class="btn-group btn-group-sm mt-2"><button class="btn btn-outline-success" :disabled="c.statutValidation==='VALIDEE'" @click="declarer(c,'TERMINE')">Terminé</button><button class="btn btn-outline-warning" :disabled="c.statutValidation==='VALIDEE'" @click="declarer(c,'TERMINE_HEURES_SUP')">Terminé + heures sup.</button><button class="btn btn-outline-secondary" :disabled="c.statutValidation==='VALIDEE'" @click="declarer(c,'NON_TERMINE')">Pas terminé</button></div></article></div><p v-if="!creneaux.length" class="text-body-secondary">Aucun créneau ce mois-ci.</p></div></div></div></div></template>
